class Solution {
 public:
  std::string AlienOrder(std::vector<std::string>& words) {
    std::map<char, std::set<char>> graph;
    for (auto& w : words)
      for (char c : w)
        graph[c];
    for (size_t i = 1; i < words.size(); i++) {
      auto& a = words[i - 1];
      auto& b = words[i];
      size_t j = 0;
      while (j < std::min(a.size(), b.size()) && a[j] == b[j])
        j++;
      if (j == std::min(a.size(), b.size())) {
        if (a.size() > b.size())
          return "";
      } else
        graph[a[j]].insert(b[j]);
    }
    std::map<char, int> degree;
    for (auto p : graph)
      degree[p.first] = 0;
    for (auto p : graph)
      for (char c : p.second)
        degree[c]++;
    std::set<char> ready;
    for (auto p : degree)
      if (!p.second)
        ready.insert(p.first);
    std::string out;
    while (!ready.empty()) {
      char c = *ready.begin();
      ready.erase(c);
