def can_finish(numCourses: int, prerequisites: list[list[int]]) -> bool:
    graph = [[] for _ in range(numCourses)]
    degree = [0] * numCourses
    for a, b in prerequisites:
        graph[b].append(a)
        degree[a] += 1
    q = deque((i for i in range(numCourses) if degree[i] == 0))
    count = 0
    while q:
        v = q.popleft()
        count += 1
        for u in graph[v]:
            degree[u] -= 1
            if degree[u] == 0:
                q.append(u)
    return count == numCourses

