public class WordDictionary
{
    private sealed class Branch
    {
        public readonly Dictionary<char, Branch> Children = new();
        public bool Terminal;
    }
    private readonly Branch root = new();
    public void AddWord(string word)
    {
        var node = root;
        foreach (char c in word)
        {
            if (!node.Children.TryGetValue(c, out var next))
            {
                next = new Branch();
                node.Children[c] = next;
            }
            node = next;
        }
        node.Terminal = true;
    }
    public bool Search(string pattern)
    {
        bool Visit(Branch node, int index)
        {
            if (index == pattern.Length)
                return node.Terminal;
            if (pattern[index] == '.')
                return node.Children.Values.Any(child => Visit(child, index + 1));
            return node.Children.TryGetValue(pattern[index], out var child) &&
                   Visit(child, index + 1);
        }
        return Visit(root, 0);
    }
