class Solution {
 public:
  bool ValidTree(int n, std::vector<std::vector<int>>& edges) {
    if (n == 0 || edges.size() != static_cast<size_t>(n - 1))
      return false;
    std::vector<int> parent(n);
    for (int i = 0; i < n; i++)
      parent[i] = i;
    auto find = [&](int v) {
      while (v != parent[v]) {
        parent[v] = parent[parent[v]];
        v = parent[v];
      }
      return v;
    };
    int count = n;
    for (auto e : edges) {
      int a = find(e[0]), b = find(e[1]);
      if (a != b) {
        parent[a] = b;
        count--;
      }
    }
    return count == 1;
  }
};

