public class Solution
{
    public bool ValidTree(int n, int[][] edges)
    {
        if (n == 0 || edges.Length != n - 1)
            return false;
        var parent = Enumerable.Range(0, n).ToArray();
        int Find(int v)
        {
            while (v != parent[v])
            {
                parent[v] = parent[parent[v]];
                v = parent[v];
            }
            return v;
        }
        int count = n;
        foreach (var e in edges)
        {
            int a = Find(e[0]), b = Find(e[1]);
            if (a != b)
            {
                parent[a] = b;
                count--;
            }
        }
        return count == 1;
    }
}

