public class Trie
{
    private sealed class Branch
    {
        public readonly Dictionary<char, Branch> Children = new();
        public bool Terminal;
    }
    private readonly Branch root = new();
    private Branch? Follow(string text)
    {
        var node = root;
        foreach (char c in text)
        {
            if (!node.Children.TryGetValue(c, out var next))
                return null;
            node = next;
        }
        return node;
    }
    public void Insert(string word)
    {
        var node = root;
        foreach (char c in word)
        {
            if (!node.Children.TryGetValue(c, out var next))
            {
                next = new Branch();
                node.Children[c] = next;
            }
            node = next;
        }
        node.Terminal = true;
    }
    public bool Search(string word) => Follow(word)?.Terminal == true;
    public bool StartsWith(string prefix) => (root.Terminal || root.Children.Count > 0) &&
                                             Follow(prefix) is not null;
}

