  std::vector<std::vector<int>> Insert(std::vector<std::vector<int>>& intervals,
                                       std::vector<int>& newInterval) {
    auto rows = intervals;
    rows.push_back(newInterval);
    std::sort(rows.begin(), rows.end());
    std::vector<std::vector<int>> out;
    for (auto row : rows) {
      if (!out.empty() && row[0] <= out.back()[1])
        out.back()[1] = std::max(out.back()[1], row[1]);
      else
        out.push_back(row);
    }
    return out;
  }
};

