public class Solution {
  public int[][] insert(int[][] intervals, int[] newInterval) {
    int[][] rows = Arrays.copyOf(intervals, intervals.length + 1);
    rows[intervals.length] = newInterval;
    Arrays.sort(rows, Comparator.comparingInt(r -> r[0]));
    List<int[]> out = new ArrayList<>();
    for (int[] row : rows) {
      if (!out.isEmpty() && row[0] <= out.get(out.size() - 1)[1])
        out.get(out.size() - 1)[1] = Math.max(out.get(out.size() - 1)[1], row[1]);
      else
        out.add(row.clone());
    }
    return out.toArray(int[][] ::new);
  }
}

