class Solution {
 public:
  int LongestConsecutive(std::vector<int>& nums) {
    std::unordered_set<int> seen(nums.begin(), nums.end());
    int best = 0;
    for (int v : seen)
      if (!seen.count(v - 1)) {
        int end = v;
        while (seen.count(end))
          end++;
        best = std::max(best, end - v);
      }
    return best;
  }
};

