class Solution {
 public:
  int LengthOfLIS(std::vector<int>& nums) {
    std::vector<int> tails;
    for (int v : nums) {
      auto it = std::lower_bound(tails.begin(), tails.end(), v);
      if (it == tails.end())
        tails.push_back(v);
      else
        *it = v;
    }
    return static_cast<int>(tails.size());
  }
};

