public class Solution
{
    public int MinMeetingRooms(int[][] intervals)
    {
        var events =
            intervals
                .SelectMany(row => new[] { (time: row[0], delta: 1), (time: row[1], delta: -1) })
                .OrderBy(e => e.time)
                .ThenBy(e => e.delta);
        int active = 0, best = 0;
        foreach (var e in events)
        {
            active += e.delta;
            best = Math.Max(best, active);
        }
        return best;
    }
}

