    for (int[] row : intervals) {
      events.add(new int[] {row[0], 1});
      events.add(new int[] {row[1], -1});
    }
    events.sort((a, b) -> a[0] == b[0] ? Integer.compare(a[1], b[1]) : Integer.compare(a[0], b[0]));
    int active = 0, best = 0;
    for (int[] e : events) {
      active += e[1];
      best = Math.max(best, active);
    }
    return best;
  }
}

