entries.solutionCode:
class Solution {
 public:
  int CountComponents(int n, std::vector<std::vector<int>>& edges) {
    std::vector<int> parent(n);
    for (int i = 0; i < n; i++)
      parent[i] = i;
    auto find = [&](int v) {
      while (v != parent[v]) {
        parent[v] = parent[parent[v]];
        v = parent[v];
      }
      return v;
    };
    int count = n;
    for (auto e : edges) {
      int a = find(e[0]), b = find(e[1]);
      if (a != b) {
        parent[a] = b;
        count--;
      }
    }
    return count;
  }
};

