def count_components(n: int, edges: list[list[int]]) -> int:
    return component_count(n, edges)


def component_count(n, edges):
    parent = list(range(n))
    count = n

    def find(v):
        while v != parent[v]:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v

    for u, v in edges:
        a, b = (find(u), find(v))
        if a != b:
            parent[a] = b
            count -= 1
    return count

