public class Solution
{
    public ListNode? RemoveNthFromEnd(ListNode? head, int n)
    {
        var dummy = new ListNode(0, head);
        var fast = dummy;
        for (int i = 0; i < n; i++)
            fast = fast.next!;
        var slow = dummy;
        while (fast.next is not null)
        {
            fast = fast.next;
            slow = slow.next!;
        }
        slow.next = slow.next!.next;
        return dummy.next;
    }
}

