 public:
  std::vector<int> SpiralOrder(std::vector<std::vector<int>>& matrix) {
    std::vector<int> out;
    int top = 0, bottom = static_cast<int>(matrix.size()) - 1, left = 0,
        right = static_cast<int>(matrix[0].size()) - 1;
    while (top <= bottom && left <= right) {
      for (int c = left; c <= right; c++)
        out.push_back(matrix[top][c]);
      top++;
      for (int r = top; r <= bottom; r++)
        out.push_back(matrix[r][right]);
      right--;
      if (top <= bottom) {
        for (int c = right; c >= left; c--)
          out.push_back(matrix[bottom][c]);
        bottom--;
      }
      if (left <= right) {
        for (int r = bottom; r >= top; r--)
          out.push_back(matrix[r][left]);
        left++;
      }
    }
    return out;
  }
};

