class Solution {
 public:
  std::vector<int> TopKFrequent(std::vector<int>& nums, int k) {
    std::unordered_map<int, int> counts;
    for (int v : nums)
      counts[v]++;
    std::vector<std::pair<int, int>> a;
    for (auto p : counts)
      a.emplace_back(p.second, p.first);
    std::sort(a.rbegin(), a.rend());
    std::vector<int> out;
    for (int i = 0; i < k; i++)
      out.push_back(a[i].second);
    return out;
  }
};

