public class Solution {
  public int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> counts = new HashMap<>();
    for (int v : nums)
      counts.merge(v, 1, Integer::sum);
    return counts.keySet()
        .stream()
        .sorted((a, b) -> Integer.compare(counts.get(b), counts.get(a)))
        .limit(k)
        .mapToInt(v -> v)
        .toArray();
  }
}

