class Solution {
 public:
  bool IsPalindrome(std::string s) {
    std::string a;
    for (unsigned char c : s)
      if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'))
        a.push_back(c >= 'A' && c <= 'Z' ? c - 'A' + 'a' : c);
    auto b = a;
    std::reverse(b.begin(), b.end());
    return a == b;
  }
};

