public static class Algorithms
{
    public static IEnumerable<int> Inorder(TreeNode? node)
    {
        var stack = new Stack<TreeNode>();
        while (node is not null || stack.Count > 0)
        {
            while (node is not null)
            {
                stack.Push(node);
                node = node.left;
            }
            node = stack.Pop();
            yield return node.val;
            node = node.right;
        }
    }
}

