class Solution {
 public:
  bool Exist(std::vector<std::string>& board, std::string word) {
    int rows = static_cast<int>(board.size()), cols = static_cast<int>(board[0].size());
    std::vector<std::vector<bool>> used(rows, std::vector<bool>(cols));
    std::function<bool(int, int, int)> visit = [&](int r, int c, int i) {
      if (r < 0 || r >= rows || c < 0 || c >= cols || used[r][c] || board[r][c] != word[i])
        return false;
      if (i == static_cast<int>(word.size()) - 1)
        return true;
      used[r][c] = true;
      bool ok = visit(r - 1, c, i + 1) || visit(r + 1, c, i + 1) || visit(r, c - 1, i + 1) ||
                visit(r, c + 1, i + 1);
      used[r][c] = false;
      return ok;
    };
    for (int r = 0; r < rows; r++)
      for (int c = 0; c < cols; c++)
        if (visit(r, c, 0))
          return true;
    return false;
  }
};

