private static BstNode<Integer> buildMinHeightBSTFromSortedSubarray(
    List<Integer> A, int start, int end) {
  if (start >= end) {
    return null;
  }
  int mid = start + ((end - start) / 2);
  return new BstNode<>(A.get(mid), buildMinHeightBSTFromSortedSubarray(A, start, mid),
      buildMinHeightBSTFromSortedSubarray(A, mid + 1, end));
}

