class Queue {
 public:
  explicit Queue(std::size_t capacity) : entries_(std::max(std::size_t{1}, capacity)) {
  }

  explicit Queue(int capacity)
      : Queue(capacity > 0 ? static_cast<std::size_t>(capacity) : std::size_t{1}) {
  }

  void Enqueue(int value) {
    if (count_ == entries_.size()) {
      std::vector<int> expanded(entries_.size() * 2);
      for (std::size_t index = 0; index < count_; ++index) {
        expanded[index] = entries_[(head_ + index) % entries_.size()];
      }
      entries_.swap(expanded);
      head_ = 0;
    }
    entries_[(head_ + count_) % entries_.size()] = value;
    ++count_;
  }

  int Dequeue() {
    if (count_ == 0)
      throw std::underflow_error("The queue is empty.");
    const int result = entries_[head_];
    head_ = (head_ + 1) % entries_.size();
    --count_;
    return result;
  }

  int Size() const {
    return static_cast<int>(count_);
  }

 private:
  std::vector<int> entries_;
  std::size_t head_ = 0;
  std::size_t count_ = 0;
};

