  std::vector<std::string> GroupAnagrams(std::vector<std::string>& words) {
    std::vector<std::pair<std::string, std::string>> decorated;
    decorated.reserve(words.size());
    for (const auto& word : words) {
      auto key = word;
      std::sort(key.begin(), key.end());
