function EncodeXml(
  elementNames,
  elementTexts,
  children,
  attributeOwners,
  attributeNames,
  attributeValues,
  codeNames,
  codes,
) {
  if (elementNames.length === 0) return [];
  const lookup = new Map(codeNames.map((name, i) => [name, String(codes[i])])),
    attributes = Array.from({ length: elementNames.length }, () => []),
    result = [],
    events = [[0, false]];
  for (let i = 0; i < attributeOwners.length; ++i) attributes[attributeOwners[i]].push(i);
  while (events.length) {
    const [node, exiting] = events.pop();
    if (exiting) {
      result.push("0");
      continue;
    }
    result.push(lookup.get(elementNames[node]));
    for (const attribute of attributes[node])
      result.push(lookup.get(attributeNames[attribute]), attributeValues[attribute]);
    result.push("0");
    events.push([node, true]);
    if (elementTexts[node].length) result.push(elementTexts[node]);
    else
      for (let i = children[node].length - 1; i >= 0; --i) events.push([children[node][i], false]);
  }
  return result;
}

def EncodeXml(
    elementNames: list[str],
    elementTexts: list[str],
    children: list[list[int]],
    attributeOwners: list[int],
    attributeNames: list[str],
    attributeValues: list[str],
    codeNames: list[str],
    codes: list[int],
) -> list[str]:
    if not elementNames:
        return []
    lookup = {name: str(code) for name, code in zip(codeNames, codes)}
    attributes = [[] for _ in elementNames]
    for index, owner in enumerate(attributeOwners):
        attributes[owner].append(index)
    result = []
    events = [(0, False)]
    while events:
        node, exiting = events.pop()
        if exiting:
            result.append("0")
            continue
        result.append(lookup[elementNames[node]])
        for attribute in attributes[node]:
            result.extend([lookup[attributeNames[attribute]], attributeValues[attribute]])
        result.append("0")
        events.append((node, True))
        if elementTexts[node]:
            result.append(elementTexts[node])
        else:
            for child in reversed(children[node]):
                events.append((child, False))
    return result

