  std::vector<int> MissingTwo(const std::vector<int>& values) {
    int n = static_cast<int>(values.size()) + 2, combined = 0;
    for (int value = 1; value <= n; ++value)
      combined ^= value;
    for (int value : values)
      combined ^= value;
