    for (int value = 1; value <= n; ++value) {
      if ((value & bit) != 0)
        first ^= value;
      else
        second ^= value;
    }
    for (int value : values) {
      if ((value & bit) != 0)
        first ^= value;
      else
        second ^= value;
    }
    return {std::min(first, second), std::max(first, second)};
  }
};

