function LargestWordRectangle(words) {
  const groups = new Map(),
    seen = new Set();
  let maximum = 0;
  for (const word of words)
    if (!seen.has(word)) {
      seen.add(word);
      if (!groups.has(word.length)) groups.set(word.length, []);
      groups.get(word.length).push(word);
      maximum = Math.max(maximum, word.length);
    }
  for (let area = maximum * maximum; area > 0; --area)
    for (let height = 1; height <= maximum; ++height) {
      if (area % height !== 0) continue;
      const width = area / height;
      if (!groups.has(width) || !groups.has(height)) continue;
      const prefixes = new Set();
      for (const word of groups.get(height))
        for (let length = 1; length <= height; ++length) prefixes.add(word.slice(0, length));
      const rows = [];
      function search() {
        if (rows.length === height) return true;
        for (const word of groups.get(width)) {
          rows.push(word);
          let valid = true;
          for (let column = 0; column < width; ++column) {
            let prefix = "";
            for (const row of rows) prefix += row[column];
            if (!prefixes.has(prefix)) {
              valid = false;
              break;
            }
          }
          if (valid && search()) return true;
          rows.pop();
        }
        return false;
      }
      if (search()) return rows;
    }
  return [];
}

def LargestWordRectangle(words: list[str]) -> list[str]:
    groups = {}
    seen = set()
    maximum = 0
    for word in words:
        if word not in seen:
            seen.add(word)
            groups.setdefault(len(word), []).append(word)
            maximum = max(maximum, len(word))
    for area in range(maximum * maximum, 0, -1):
        for height in range(1, maximum + 1):
            if area % height:
                continue
            width = area // height
            if width not in groups or height not in groups:
                continue
            prefixes = {word[:length] for word in groups[height] for length in range(1, height + 1)}
            rows = []

            def search():
                if len(rows) == height:
                    return True
                for word in groups[width]:
                    rows.append(word)
                    if (
                        all(
                            "".join(row[column] for row in rows) in prefixes
                            for column in range(width)
                        )
                        and search()
                    ):
                        return True
                    rows.pop()
                return False

            if search():
                return rows
    return []

