class TwoStackQueue {
  std::vector<int> newest, oldest;
  void Shift() {
    if (oldest.size() == 0) {
      while (!(newest.size() == 0)) {
        oldest.push_back(newest.back());
        newest.pop_back();
      }
    }
  }

 public:
  TwoStackQueue() = default;
  void Add(int value) {
    newest.push_back(value);
  }
  int Remove() {
    Shift();
    if (oldest.size() == 0)
      throw BankError("empty");
    int value = oldest.back();
    oldest.pop_back();
    return value;
  }
  int Peek() {
    Shift();
    if (oldest.size() == 0)
      throw BankError("empty");
    return oldest.back();
  }
  int Size() {
    return static_cast<int>(newest.size() + oldest.size());
  }
};

