function PaintFill(screen, row, column, newColor) {
  const rows = screen.length,
    columns = rows ? screen[0].length : 0;
  if (row < 0 || row >= rows || column < 0 || column >= columns) return screen;
  const oldColor = screen[row][column];
  if (oldColor === newColor) return screen;
  const work = [[row, column]];
  screen[row][column] = newColor;
  while (work.length) {
    const [r, c] = work.pop();
    for (const [nr, nc] of [
      [r - 1, c],
      [r + 1, c],
      [r, c - 1],
      [r, c + 1],
    ]) {
      if (nr >= 0 && nr < rows && nc >= 0 && nc < columns && screen[nr][nc] === oldColor) {
        screen[nr][nc] = newColor;
        work.push([nr, nc]);
      }
    }
  }
  return screen;
}

def PaintFill(screen: list[list[int]], row: int, column: int, newColor: int) -> list[list[int]]:
    rows = len(screen)
    columns = len(screen[0]) if rows else 0
    if row < 0 or row >= rows or column < 0 or column >= columns:
        return screen
    old_color = screen[row][column]
    if old_color == newColor:
        return screen
    work = [(row, column)]
    screen[row][column] = newColor
    while work:
        r, c = work.pop()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < columns and screen[nr][nc] == old_color:
                screen[nr][nc] = newColor
                work.append((nr, nc))
    return screen

