function huffmanEncoding(symbols) {
  class Heap {
    constructor(compare) {
      this.a = [];
      this.compare = compare;
    }
    get size() {
      return this.a.length;
    }
    peek() {
      return this.a[0];
    }
    push(value) {
      const a = this.a;
      a.push(value);
      let i = a.length - 1;
      while (i) {
        const p = Math.floor((i - 1) / 2);
        if (this.compare(a[p], a[i]) <= 0) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
      }
    }
    pop() {
      const a = this.a;
      if (!a.length) throw new RangeError("Empty heap");
      const result = a[0],
        last = a.pop();
      if (a.length) {
        a[0] = last;
        let i = 0;
        for (;;) {
          let c = 2 * i + 1;
          if (c >= a.length) break;
          if (c + 1 < a.length && this.compare(a[c + 1], a[c]) < 0) c++;
          if (this.compare(a[i], a[c]) <= 0) break;
          [a[i], a[c]] = [a[c], a[i]];
          i = c;
        }
      }
      return result;
    }
  }
  const weights = new Heap((a, b) => a - b);
  for (const [, frequency] of symbols) weights.push(frequency);
  let cost = 0;
  while (weights.size > 1) {
    const combined = weights.pop() + weights.pop();
    cost += combined;
    weights.push(combined);
  }
  return cost / 100;
}

import collections

import heapq

from typing import Dict, List


def huffman_encoding(symbols: List[CharWithFrequency]) -> float:
    if not symbols:
        return 0.0

    class BinaryTree:
        def __init__(self, aggregate_freq, s, left=None, right=None):
            self.aggregate_freq = aggregate_freq
            self.s = s
            self.left, self.right = left, right

        def __lt__(self, other):
            return self.aggregate_freq <= other.aggregate_freq

        def symbols(self):
            return self.left.symbols() + self.right.symbols() if self.s is None else self.s.c

        def __repr__(self):
            return "%s <- %r(%g) -> %s" % (
                self.left and self.left.symbols(),
                self.symbols(),
                self.aggregate_freq,
                self.right and self.right.symbols(),
            )

    # Initially assigns each symbol into candidates.
    candidates = [BinaryTree(s.freq, s) for s in symbols]
    heapq.heapify(candidates)

    # Keeps combining two nodes until there is one node left.
    while len(candidates) > 1:
        left, right = heapq.heappop(candidates), heapq.heappop(candidates)
        heapq.heappush(
            candidates, BinaryTree(left.aggregate_freq + right.aggregate_freq, None, left, right)
        )

    def assign_huffman_code(tree, code):
        if tree:
            if tree.s:
                # This node is a leaf.
                char_to_encoding[tree.s.c] = "".join(code)
            else:  # Non-leaf node.
                code.append("0")
                assign_huffman_code(tree.left, code)
                code[-1] = "1"
                assign_huffman_code(tree.right, code)
                del code[-1]

    char_to_encoding: Dict[str, str] = {}
    # Traverses the binary tree, assigning codes to nodes.
    assign_huffman_code(candidates[0], [])
    return sum(len(char_to_encoding[s.c]) * s.freq / 100 for s in symbols)

