    L1 = L1 ? L1->next : nullptr;
    L2 = L2 ? L2->next : nullptr;
    place_iter->next = make_shared<ListNode<int>>(val % 10, nullptr);
    carry = val / 10, place_iter = place_iter->next;
  }
  return dummy_head->next;
}

