class Solution {
 public:
  bool IsBalanced(BinaryTreeNode* root) {
    if (!root)
      return true;
    vector<pair<BinaryTreeNode*, int>> pending{{root, 0}};
    int shallowest = numeric_limits<int>::max();
    int deepest = 0;
    while (!pending.empty()) {
      auto [node, depth] = pending.back();
      pending.pop_back();
      if (!node->Left && !node->Right) {
        shallowest = min(shallowest, depth);
        deepest = max(deepest, depth);
        if (deepest - shallowest > 1)
          return false;
      }
      if (node->Left)
        pending.push_back({node->Left, depth + 1});
      if (node->Right)
        pending.push_back({node->Right, depth + 1});
    }
    return true;
  }
};

