class Solution {
  private record Entry(BinaryTreeNode node, int depth) {}
  public boolean IsBalanced(BinaryTreeNode root) {
    if (root == null)
      return true;
    ArrayDeque<Entry> pending = new ArrayDeque<>();
    pending.push(new Entry(root, 0));
    int shallowest = Integer.MAX_VALUE, deepest = 0;
    while (!pending.isEmpty()) {
      Entry current = pending.pop();
      BinaryTreeNode node = current.node();
      if (node.Left == null && node.Right == null) {
        shallowest = Math.min(shallowest, current.depth());
        deepest = Math.max(deepest, current.depth());
        if (deepest - shallowest > 1)
          return false;
      }
      if (node.Left != null)
        pending.push(new Entry(node.Left, current.depth() + 1));
      if (node.Right != null)
        pending.push(new Entry(node.Right, current.depth() + 1));
    }
    return true;
  }
}

