class Solution {
  private record Entry(BinaryTreeNode node, long low, long high) {}
  public boolean IsBinarySearchTree(BinaryTreeNode root) {
    if (root == null)
      return true;
    var pending = new ArrayDeque<Entry>();
    pending.push(new Entry(root, Long.MIN_VALUE, Long.MAX_VALUE));
    while (!pending.isEmpty()) {
      var current = pending.pop();
      var node = current.node();
      if (node.Value <= current.low() || node.Value >= current.high())
        return false;
      if (node.Left != null)
        pending.push(new Entry(node.Left, current.low(), node.Value));
      if (node.Right != null)
        pending.push(new Entry(node.Right, node.Value, current.high()));
    }
    return true;
  }
}

