class Solution {
 public:
  bool IsFirstComeFirstServed(vector<int>& takeOut, vector<int>& dineIn, vector<int>& served) {
    if (served.size() != takeOut.size() + dineIn.size())
      return false;
    size_t take = 0, dine = 0;
    for (int order : served) {
      if (take < takeOut.size() && takeOut[take] == order)
        ++take;
      else if (dine < dineIn.size() && dineIn[dine] == order)
        ++dine;
      else
        return false;
    }
    return take == takeOut.size() && dine == dineIn.size();
  }
};

