class Solution {
  public long MaxDuffelBagValue(CakeType[] types, int capacity) {
    for (CakeType type : types)
      if (type.Weight == 0 && type.Value > 0)
        throw new InfinityException();
    long[] best = new long[capacity + 1];
    for (int weight = 1; weight <= capacity; weight++)
      for (CakeType type : types)
        if (type.Weight > 0 && type.Weight <= weight)
          best[weight] = Math.max(best[weight], best[weight - type.Weight] + type.Value);
    return best[capacity];
  }
}

