class Solution {
  private static String Fingerprint(Path file) throws IOException {
    long size = Files.size(file);
    int count = (int) Math.min(64L, size);
    long end = Math.max(0L, size - 64L);
    long[] offsets = {0L, end / 2L, end};
    StringBuilder key = new StringBuilder().append(size);
    try (RandomAccessFile input = new RandomAccessFile(file.toFile(), "r")) {
      for (long offset : offsets) {
        byte[] sample = new byte[count];
        input.seek(offset);
        input.readFully(sample);
        key.append(':').append(Base64.getEncoder().encodeToString(sample));
      }
    }
    return key.toString();
  }
  public List<FilePaths> FindDuplicateFiles(String startingDirectory) {
    var firstByFingerprint = new HashMap<String, Path>();
    var result = new ArrayList<FilePaths>();
    try (var paths = Files.walk(Paths.get(startingDirectory))) {
      var files = paths.filter(Files::isRegularFile).iterator();
      while (files.hasNext()) {
        Path file = files.next().toAbsolutePath().normalize();
        String key = Fingerprint(file);
        Path earlier = firstByFingerprint.putIfAbsent(key, file);
        if (earlier != null) {
          Path original = earlier, duplicate = file;
          if (Files.getLastModifiedTime(file).toMillis()
              < Files.getLastModifiedTime(earlier).toMillis()) {
            original = file;
            duplicate = earlier;
          }
          result.add(new FilePaths(original.toString(), duplicate.toString()));
        }
      }
    } catch (IOException error) {
      throw new UncheckedIOException(error);
    }
    return result;
  }
}

