class Solution {
 public:
  int FindRepeat(vector<int>& numbers) {
    int low = 1, high = static_cast<int>(numbers.size()) - 1;
    while (low < high) {
      int middle = low + (high - low) / 2;
      int count = 0;
      for (int value : numbers)
        if (low <= value && value <= middle)
          ++count;
      if (count > middle - low + 1)
        high = middle;
      else
        low = middle + 1;
    }
    return low;
