class Solution {
 public:
  int HighestProductOf3(vector<int>& values) {
    int first = numeric_limits<int>::min(), second = first, third = first;
    int smallest = numeric_limits<int>::max(), nextSmallest = smallest;
    for (int value : values) {
      if (value >= first) {
        third = second;
        second = first;
        first = value;
      } else if (value >= second) {
        third = second;
        second = value;
      } else
        third = max(third, value);
      if (value <= smallest) {
        nextSmallest = smallest;
        smallest = value;
      } else
        nextSmallest = min(nextSmallest, value);
    }
    return max(first * second * third, first * smallest * nextSmallest);
  }
};

