public class Solution
{
    public int HighestProductOf3(int[] values)
    {
        if (values.Length < 3)
            throw new ArgumentException();
        int high = Math.Max(values[0], values[1]), low = Math.Min(values[0], values[1]);
        int highTwo = values[0] * values[1], lowTwo = highTwo, best = highTwo * values[2];
        for (int i = 2; i < values.Length; i++)
        {
            int x = values[i];
            best = Math.Max(best, Math.Max(x * highTwo, x * lowTwo));
            highTwo = Math.Max(highTwo, Math.Max(x * high, x * low));
            lowTwo = Math.Min(lowTwo, Math.Min(x * high, x * low));
            high = Math.Max(high, x);
            low = Math.Min(low, x);
        }
        return best;
    }
}

