public class Solution
{
    public LinkedListNode KthToLastNode(int k, LinkedListNode? head)
    {
        if (k < 1)
            throw new ArgumentOutOfRangeException(nameof(k));
        var lead = head;
        for (int i = 0; i < k; i++)
        {
            if (lead is null)
                throw new ArgumentOutOfRangeException(nameof(k));
            lead = lead.Next;
        }
        var follow = head;
        while (lead is not null)
        {
            lead = lead.Next;
            follow = follow!.Next;
        }
        return follow!;
    }
}

