public class MaxStack
{
    private readonly Stack<int> values = new();
    private readonly Stack<int> maxima = new();
    public void Push(int item)
    {
        values.Push(item);
        if (maxima.Count == 0 || item >= maxima.Peek())
            maxima.Push(item);
    }
    public int Pop()
    {
        int value = values.Pop();
        if (value == maxima.Peek())
            maxima.Pop();
        return value;
    }
    public int GetMax() => maxima.Peek();
}

