class Solution {
  public List<Meeting> MergeRanges(List<Meeting> meetings) {
    var sorted = new ArrayList<>(meetings);
    sorted.sort(Comparator.comparingInt(meeting -> meeting.StartTime));
    var result = new ArrayList<Meeting>();
    for (Meeting meeting : sorted) {
      if (result.isEmpty() || meeting.StartTime > result.get(result.size() - 1).EndTime)
        result.add(new Meeting(meeting.StartTime, meeting.EndTime));
      else {
        Meeting last = result.get(result.size() - 1);
        last.EndTime = Math.max(last.EndTime, meeting.EndTime);
      }
    }
    return result;
  }
}

