public class Solution
{
    public string[]? BfsGetPath(Dictionary<string, string[]> graph, string start, string end)
    {
        if (!graph.ContainsKey(start) || !graph.ContainsKey(end))
            throw new ArgumentException();
        var previous = new Dictionary<string, string?> { { start, null } };
        var queue = new Queue<string>();
        queue.Enqueue(start);
        while (queue.Count > 0)
        {
            string current = queue.Dequeue();
            if (current == end)
            {
                var path = new List<string>();
                for (string? at = end; at is not null; at = previous[at])
                    path.Add(at);
                path.Reverse();
                return path.ToArray();
            }
            foreach (string next in graph[current])
                if (!previous.ContainsKey(next))
                {
                    previous[next] = current;
                    queue.Enqueue(next);
                }
        }
        return null;
    }
}

