 public:
  vector<int> GetProductsOfAllIntsExceptAtIndex(vector<int>& values) {
    vector<int> products(values.size(), 1);
    int prefix = 1;
    for (size_t i = 0; i < values.size(); ++i) {
      products[i] = prefix;
      prefix *= values[i];
    }
    int suffix = 1;
    for (int i = static_cast<int>(values.size()) - 1; i >= 0; --i) {
      products[i] *= suffix;
      suffix *= values[i];
    }
    return products;
  }
};

