class QueueTwoStacks {
  stack<int> incoming, outgoing;

 public:
  void Enqueue(int item) {
    incoming.push(item);
  }
  int Dequeue() {
    if (outgoing.empty()) {
      while (!incoming.empty()) {
        outgoing.push(incoming.top());
        incoming.pop();
      }
    }
    if (outgoing.empty())
      throw runtime_error("empty");
    int item = outgoing.top();
    outgoing.pop();
    return item;
  }
};

