class Solution {
 public:
  set<string> GetPermutations(const string& text) {
    if (text.empty())
      return {""};
    auto shorter = GetPermutations(text.substr(0, text.size() - 1));
    set<string> result;
    for (const auto& word : shorter) {
      for (size_t position = 0; position <= word.size(); ++position) {
        string next = word;
        next.insert(next.begin() + position, text.back());
        result.insert(next);
      }
    }
    return result;
  }
};

