class Solution {
  private void Build(char[] letters, int position, Set<String> result) {
    if (position == letters.length) {
      result.add(new String(letters));
      return;
    }
    Set<Character> chosen = new HashSet<>();
    for (int i = position; i < letters.length; i++)
      if (chosen.add(letters[i])) {
        char saved = letters[position];
        letters[position] = letters[i];
        letters[i] = saved;
        Build(letters, position + 1, result);
        saved = letters[position];
        letters[position] = letters[i];
        letters[i] = saved;
      }
  }
  public Set<String> GetPermutations(String text) {
    var result = new HashSet<String>();
    Build(text.toCharArray(), 0, result);
    return result;
  }
}

