    public void ReverseWords(char[] message)
    {
        ReverseRange(message, 0, message.Length - 1);
        int start = 0;
        for (int end = 0; end <= message.Length; end++)
            if (end == message.Length || message[end] == ' ')
            {
                ReverseRange(message, start, end - 1);
                start = end + 1;
