class Solution {
 public:
  int FindSecondLargest(BinaryTreeNode* root) {
    BinaryTreeNode* parent = nullptr;
    BinaryTreeNode* largest = root;
    while (largest->Right) {
      parent = largest;
      largest = largest->Right;
    }
    if (largest->Left) {
      auto node = largest->Left;
      while (node->Right)
        node = node->Right;
      return node->Value;
    }
    return parent->Value;
  }
};

