public class TempTracker
{
    private readonly int[] counts = new int[111];
    private long sum, count;
    private int minimum = 110, maximum = 0, mode = 0;
    public void Insert(int temperature)
    {
        if (temperature < 0 || temperature > 110)
            throw new ArgumentOutOfRangeException(nameof(temperature));
        counts[temperature]++;
        count++;
        sum += temperature;
        minimum = Math.Min(minimum, temperature);
        maximum = Math.Max(maximum, temperature);
        if (counts[temperature] > counts[mode])
            mode = temperature;
    }
    public int? GetMin() => count == 0 ? null : minimum;
    public int? GetMax() => count == 0 ? null : maximum;
    public double? GetMean() => count == 0 ? null : (double)sum / count;
    public int? GetMode() => count == 0 ? null : mode;
}

