public class Solution
{
    public int[] SortScores(int[] scores, int highestPossibleScore)
    {
        var counts = new int[highestPossibleScore + 1];
        foreach (int score in scores)
            counts[score]++;
        var result = new int[scores.Length];
        int position = 0;
        for (int score = highestPossibleScore; score >= 0; score--)
            for (int occurrence = 0; occurrence < counts[score]; occurrence++)
                result[position++] = score;
        return result;
    }
}

