public static int findLineWithMostPoints(List<Point> points) {
  int result = 0;
  for (int i = 0; i < points.size(); ++i) {
    Map<Long, Map<Long, Integer>> slopeTable = new HashMap<>();
    int overlapPoints = 1;
    for (int j = i + 1; j < points.size(); ++j) {
      if (points.get(i).x == points.get(j).x && points.get(i).y == points.get(j).y) {
        ++overlapPoints;
      } else {
        long xDiff = (long) points.get(i).x - points.get(j).x,
             yDiff = (long) points.get(i).y - points.get(j).y;
        if (xDiff == 0) {
          // A vertical line with slope 1/0.
          yDiff = 1;
        } else {
          long gcd = BigInteger.valueOf(xDiff).gcd(BigInteger.valueOf(yDiff)).longValue();
          xDiff /= gcd;
          yDiff /= gcd;
          if (xDiff < 0) {
            xDiff = -xDiff;
            yDiff = -yDiff;
          }
        }
        slopeTable.putIfAbsent(xDiff, new HashMap<>());
        slopeTable.get(xDiff).put(yDiff, slopeTable.get(xDiff).getOrDefault(yDiff, 0) + 1);
      }
    }
    result = Math.max(result,
        overlapPoints
            + (slopeTable.isEmpty()
                    ? 0
                    : Collections.max(Collections
                              .max(slopeTable.values(),
                                  Comparator.comparingInt(m -> Collections.max(m.values())))
                              .values())));
  }
  return result;
}

