void RotateMatrix(vector<vector<int>>* square_matrix_ptr) {
  vector<vector<int>>& square_matrix = *square_matrix_ptr;
  const int matrix_size = size(square_matrix) - 1;
  for (int i = 0; i < (size(square_matrix) / 2); ++i) {
