          Math.min(nearestRepeatedDistance, i - wordToLatestIndex.get(paragraph.get(i)));
    }
    wordToLatestIndex.put(paragraph.get(i), i);
  }
  return nearestRepeatedDistance != Integer.MAX_VALUE ? nearestRepeatedDistance : -1;
