public static int nonuniformRandomNumberGeneration(
    List<Integer> values, List<Double> probabilities) {
  List<Double> prefixSumOfProbabilities = new ArrayList<>();
  // Creating the endpoints for the intervals corresponding to the
  // probabilities.
  probabilities.stream().reduce(0.0, (left, right) -> {
    prefixSumOfProbabilities.add(left + right);
    return left + right;
  });

  Random r = new Random();
  // Get a random number in [0.0,1.0).
  final double uniform01 = r.nextDouble();
  // Find the first endpoint strictly greater than the draw. Equal
  // endpoints belong to the following interval, including zero-width ones.
  int low = 0, high = prefixSumOfProbabilities.size();
  while (low < high) {
    int middle = low + (high - low) / 2;
    if (prefixSumOfProbabilities.get(middle) <= uniform01)
      low = middle + 1;
    else
      high = middle;
  }
  return values.get(Math.min(low, values.size() - 1));
}

