function onlineMedian(sequence) {
  class Heap {
    constructor(compare) {
      this.a = [];
      this.compare = compare;
    }
    get size() {
      return this.a.length;
    }
    peek() {
      return this.a[0];
    }
    push(value) {
      const a = this.a;
      a.push(value);
      let i = a.length - 1;
      while (i) {
        const p = Math.floor((i - 1) / 2);
        if (this.compare(a[p], a[i]) <= 0) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
      }
    }
    pop() {
      const a = this.a;
      if (!a.length) throw new RangeError("Empty heap");
      const result = a[0],
        last = a.pop();
      if (a.length) {
        a[0] = last;
        let i = 0;
        for (;;) {
          let c = 2 * i + 1;
          if (c >= a.length) break;
          if (c + 1 < a.length && this.compare(a[c + 1], a[c]) < 0) c++;
          if (this.compare(a[i], a[c]) <= 0) break;
          [a[i], a[c]] = [a[c], a[i]];
          i = c;
        }
      }
      return result;
    }
  }
  const lower = new Heap((a, b) => b - a),
    upper = new Heap((a, b) => a - b),
    result = [];
  for (const value of sequence) {
    if (!lower.size || value <= lower.peek()) lower.push(value);
    else upper.push(value);
    if (lower.size > upper.size + 1) upper.push(lower.pop());
    if (upper.size > lower.size) lower.push(upper.pop());
    result.push(lower.size === upper.size ? (lower.peek() + upper.peek()) / 2 : lower.peek());
  }
  return result;
}

