        coins[a] +
        min(ComputeMaximumRevenueForRange(coins, a + 2, b, maximum_revenue_for_range_ptr),
            ComputeMaximumRevenueForRange(coins, a + 1, b - 1, maximum_revenue_for_range_ptr));
    int max_revenue_b =
        coins[b] +
