std::shared_ptr<ListNode<int>> ListPivoting(const std::shared_ptr<ListNode<int>>& head, int pivot) {
  std::shared_ptr<ListNode<int>> heads[3], tails[3];
  auto node = head;
  while (node) {
    auto next = node->next;
    node->next = nullptr;
    int group = node->data < pivot ? 0 : node->data == pivot ? 1 : 2;
    if (tails[group])
      tails[group]->next = node;
    else
      heads[group] = node;
    tails[group] = node;
    node = next;
  }
  std::shared_ptr<ListNode<int>> result, tail;
  for (int group = 0; group < 3; ++group)
    if (heads[group]) {
      if (tail)
        tail->next = heads[group];
      else
        result = heads[group];
      tail = tails[group];
    }
  return result;
}

