public static int divide(int x, int y) {
  int result = 0;
  int power = 32;
  long yPower = (long) y << power;
  while (x >= y) {
    while (yPower > x) {
      yPower >>>= 1;
      --power;
    }

    result += 1 << power;
    x -= yPower;
  }
  return result;
}

