class Queue {
 public:
  void Initialize() {
    incoming_ = std::stack<int>{};
    outgoing_ = std::stack<int>{};
  }
  void Enqueue(int value) {
    incoming_.push(value);
  }
  int Dequeue() {
    if (outgoing_.empty()) {
      while (!incoming_.empty()) {
        outgoing_.push(incoming_.top());
        incoming_.pop();
      }
    }
    if (outgoing_.empty())
      throw std::length_error("empty queue");
    int value = outgoing_.top();
    outgoing_.pop();
    return value;
  }

 private:
  std::stack<int> incoming_, outgoing_;
};

