private static final Random random = new Random();

public static List<Integer> computeRandomPermutation(int n) {
  List<Integer> result = new ArrayList<>(n);
  for (int i = 0; i < n; i++)
    result.add(i);
  for (int i = 0; i < n; i++)
    Collections.swap(result, i, i + random.nextInt(n - i));
  return result;
}

