long long Reverse(int x) {
  long long result = 0;
  while (x) {
    // If x is an negative, x % 10 is the negative of least significant digit.
    // For example, -256 % 10 = -6.
    result = result * 10 + x % 10;
    x /= 10;
  }
  return result;
}

