bool SearchMazeHelper(const Coordinate& cur, const Coordinate& e, vector<vector<Color>>* maze_ptr,
                      vector<Coordinate>* path_ptr) {
  auto& maze = *maze_ptr;
  // Checks cur is within maze and is a white pixel.
  if (cur.x < 0 || cur.x >= size(maze) || cur.y < 0 || cur.y >= size(maze[cur.x]) ||
      maze[cur.x][cur.y] != Color::kWhite) {
    return false;
  }
  auto& path = *path_ptr;
  path.emplace_back(cur);
  maze[cur.x][cur.y] = Color::kBlack;
  if (cur == e) {
    return true;
  }

  for (const Coordinate& next_move : vector<Coordinate>{
           {cur.x, cur.y + 1}, {cur.x, cur.y - 1}, {cur.x + 1, cur.y}, {cur.x - 1, cur.y}}) {
    if (SearchMazeHelper(next_move, e, maze_ptr, path_ptr)) {
      return true;
    }
  }
  // Cannot find a path, remove the entry added in path.emplace_back(cur).
  path.pop_back();
  return false;
}

