def binary_search_unknown_length(A: List[int], k: int) -> int:

    # Find the possible range where k exists.
    p = 0
    while True:
        try:
            idx = (1 << p) - 1  # 2^p - 1.
            if A[idx] == k:
                return idx
            elif A[idx] > k:
                break
        except IndexError:
            break
        p += 1

    # Binary search between indices 2^(p - 1) and 2^p - 2, inclusive.
    left, right = 1 << max(0, (p - 1)), (1 << p) - 2
    while left <= right:
