public static List<Integer> sortApproximatelySortedData(Iterator<Integer> sequence, int k) {
  PriorityQueue<Integer> minHeap = new PriorityQueue<>();
  // Adds the first k elements into minHeap. Stop if there are fewer than k
  // elements.
  for (int i = 0; i < k && sequence.hasNext(); ++i) {
    minHeap.add(sequence.next());
  }

  List<Integer> result = new ArrayList<>();
  // For every new element, add it to minHeap and extract the smallest.
  while (sequence.hasNext()) {
    minHeap.add(sequence.next());
    Integer smallest = minHeap.remove();
    result.add(smallest);
  }

  // sequence is exhausted, iteratively extracts the remaining elements.
  result.addAll(
      Stream.generate(minHeap::remove).limit(minHeap.size()).collect(Collectors.toList()));
  return result;
}

