std::shared_ptr<ListNode<int>> MergeParts(std::shared_ptr<ListNode<int>> a,
                                          std::shared_ptr<ListNode<int>> b) {
  auto dummy = std::make_shared<ListNode<int>>(0), tail = dummy;
  while (a && b) {
    auto& source = a->data <= b->data ? a : b;
    tail->next = source;
    source = source->next;
    tail = tail->next;
  }
  tail->next = a ? a : b;
  return dummy->next;
}

std::shared_ptr<ListNode<int>> StableSortList(std::shared_ptr<ListNode<int>> head) {
  if (!head || !head->next)
    return head;
  auto middle = head, fast = head->next;
  while (fast && fast->next) {
    middle = middle->next;
    fast = fast->next->next;
  }
  auto second = middle->next;
  middle->next = nullptr;
  return MergeParts(StableSortList(head), StableSortList(second));
}

