public static List<List<Integer>> binaryTreeDepthOrder(BinaryTreeNode<Integer> tree) {
  List<List<Integer>> result = new ArrayList<>();
  if (tree == null) {
    return result;
  }

  List<BinaryTreeNode<Integer>> currDepthNodes = List.of(tree);
  while (!currDepthNodes.isEmpty()) {
    result.add(currDepthNodes.stream().map(curr -> curr.data).collect(Collectors.toList()));
    currDepthNodes = currDepthNodes.stream()
                         .map(curr -> Arrays.asList(curr.left, curr.right))
                         .flatMap(List::stream)
                         .filter(child -> child != null)
                         .collect(Collectors.toList());
  }
  return result;
}

