std::shared_ptr<ListNode<int>> ZippingLinkedList(const std::shared_ptr<ListNode<int>>& head) {
  if (!head || !head->next)
    return head;
  auto middle = head, fast = head;
  while (fast->next && fast->next->next) {
    middle = middle->next;
    fast = fast->next->next;
  }
  auto current = middle->next;
  middle->next = nullptr;
  std::shared_ptr<ListNode<int>> reversed;
  while (current) {
    auto next = current->next;
    current->next = reversed;
    reversed = current;
    current = next;
  }
  auto first = head;
  while (reversed) {
    auto firstNext = first->next, secondNext = reversed->next;
    first->next = reversed;
    reversed->next = firstNext;
    first = firstNext;
    reversed = secondNext;
  }
  return head;
}

